import React, { CSSProperties, forwardRef } from 'react';

import { Skeleton } from './Skeleton.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { Flex } from '../flex/Flex.js';

/** Accepted properties for SkeletonText */
export interface SkeletonTextProps extends StylingProps, DataTestId {
  /**
   * Width of the SkeletonText placeholder.
   * @defaultValue 100%
   */
  width?: CSSProperties['width'];
  /**
   * Number of Lines of the SkeletonText placeholder.
   * @defaultValue 3
   */
  lines?: number;
}

/** The `SkeletonText` component renders a specified number of placeholder boxes for lines of text with an animated background. */
export const SkeletonText = forwardRef<HTMLDivElement, SkeletonTextProps>(
  (props, forwardedRef) => {
    const {
      width = '100%',
      lines = 3,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: SkeletonTextProps = props;

    const getSkeletonLinesMargin = (line: number, lines: number) => {
      if (lines === 1) {
        // do not add any margin for single-line SkeletonTexts
        return 0;
      }
      return ((line + 2) % 3) * 12;
    };

    const getSkeletonLines = (lines: number) => {
      const render: React.ReactNode[] = [];
      for (let line = 0; line < lines; line++) {
        const width = `calc(100% - ${getSkeletonLinesMargin(line, lines)}px)`;
        render.push(
          <Skeleton
            // key needs to be individual every time we render, because it resets the animation with every child drawn again.
            key={`${lines}-${line}`}
            width={width}
            height="12px"
          />,
        );
      }
      return render;
    };

    return (
      <Flex
        data-testid={dataTestId}
        ref={forwardedRef}
        flexDirection="column"
        gap={8}
        paddingY={4}
        className={consumerClassName}
        style={{ width: width, ...consumerStyle }}
        {...remainingProps}
      >
        {getSkeletonLines(lines)}
      </Flex>
    );
  },
);
